-- Used only by the isolated loopback nistiprint_test acceptance database.
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role; END IF;
END $$;
DROP TABLE IF EXISTS public.mercadolivre_personalization_batch_items,
 public.mercadolivre_personalization_logs,public.mercadolivre_personalizations,
 public.mercadolivre_chat_conversations,public.mercadolivre_personalization_batches,
 public.itens_pedido,public.pedidos,public.installed_integrations CASCADE;
CREATE TABLE public.installed_integrations(id integer PRIMARY KEY,module_id text);
CREATE TABLE public.pedidos(id integer PRIMARY KEY,marketplace_integration_id integer,marketplace_module_id text);
CREATE TABLE public.itens_pedido(id integer PRIMARY KEY,pedido_id integer);
CREATE TABLE public.mercadolivre_personalization_batches(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),marketplace_integration_id integer NOT NULL REFERENCES public.installed_integrations(id),
 pack_ids jsonb NOT NULL DEFAULT '[]',total integer NOT NULL DEFAULT 0,processed integer NOT NULL DEFAULT 0,
 attempts integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'PENDING',force boolean NOT NULL DEFAULT false,
 error_message text,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,run_token uuid,
 created_by bigint,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz);
CREATE UNIQUE INDEX uq_ml_personalization_one_running_batch_per_account
 ON public.mercadolivre_personalization_batches(marketplace_integration_id) WHERE status='RUNNING';
CREATE TABLE public.mercadolivre_personalization_batch_items(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 batch_id uuid NOT NULL REFERENCES public.mercadolivre_personalization_batches(id) ON DELETE CASCADE,
 marketplace_integration_id integer NOT NULL,pack_id text NOT NULL,status text NOT NULL DEFAULT 'PENDING'
 CHECK(status IN ('PENDING','RUNNING','COMPLETED','FAILED')),attempts integer NOT NULL DEFAULT 0,error_message text,
 started_at timestamptz,finished_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,pack_id));
CREATE TABLE public.mercadolivre_chat_conversations(
 marketplace_integration_id integer,pack_id text,context_hash text,ai_status text,needs_review boolean,
 last_ai_executed_at timestamptz,last_error text,updated_at timestamptz,PRIMARY KEY(marketplace_integration_id,pack_id));
CREATE TABLE public.mercadolivre_personalizations(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,marketplace_integration_id integer,pedido_id integer,
 item_pedido_id integer,pack_id text,provider_order_id text,provider_item_id text,provider_message_id text,
 quantity_to_personalize integer,customization_name text,customization_initial text,status text,reasoning text,
 context_hash text,source text,confirmed boolean,confirmed_by integer,confirmed_at timestamptz,
 details jsonb,updated_at timestamptz DEFAULT now(),
 UNIQUE(marketplace_integration_id,pedido_id,item_pedido_id,provider_item_id,context_hash));
CREATE TABLE public.mercadolivre_personalization_logs(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,marketplace_integration_id integer,batch_id uuid,
 pack_id text,pedido_id integer,status text,input_data text,error_message text,model_result jsonb,metadata jsonb);
